Fixes: 924f4fb003ba ("NFSD: convert write_threads to netlink command")
Cc: stable@vger.kernel.org
Reported-by: syzbot+dd3b43aa0204089217ee@syzkaller.appspotmail.com
Closes: https://lore.kernel.org/all/69744674.a00a0220.33ccc7.0000.GAE@google.com/
Tested-by: syzbot+dd3b43aa0204089217ee@syzkaller.appspotmail.com
Signed-off-by: Kuniyuki Iwashima <kuniyu@google.com>
Reviewed-by: Jeff Layton <jlayton@kernel.org>
Signed-off-by: Chuck Lever <chuck.lever@oracle.com>

Here is the root cause:
In nfsd_nl_threads_set_doit(), get_current_cred() was used to pass the current credentials to nfsd_svc(), but the extra reference count obtained by get_current_cred() was never released, leading to a memory leak of struct cred. The function should have used current_cred() which does not take an additional reference.

Here is the patch:
  */
 int nfsd_nl_threads_set_doit(struct sk_buff *skb, struct genl_info *info)
 {
 	int *nthreads, nrpools = 0, i, ret = -EOPNOTSUPP, rem;
 	struct net *net = genl_info_net(info);
 	struct nfsd_net *nn = net_generic(net, nfsd_net_id);
 	const struct nlattr *attr;
 	const char *scope = NULL;

 	if (GENL_REQ_ATTR_CHECK(info, NFSD_A_SERVER_THREADS))
 		return -EINVAL;

 	/* count number of SERVER_THREADS values */
 	nlmsg_for_each_attr_type(attr, NFSD_A_SERVER_THREADS, info->nlhdr,
 				 GENL_HDRLEN, rem)
 		nrpools++;

 	mutex_lock(&nfsd_mutex);

 	nthreads = kcalloc(nrpools, sizeof(int), GFP_KERNEL);
 	if (!nthreads) {
 		ret = -ENOMEM;
 		goto out_unlock;
 	}

 	i = 0;
 	nlmsg_for_each_attr_type(attr, NFSD_A_SERVER_THREADS, info->nlhdr,
 				 GENL_HDRLEN, rem) {
 		nthreads[i++] = nla_get_u32(attr);
 		if (i >= nrpools)
 			break;
 	}

 	if (info->attrs[NFSD_A_SERVER_GRACETIME] ||
 	    info->attrs[NFSD_A_SERVER_LEASETIME] ||
 	    info->attrs[NFSD_A_SERVER_SCOPE]) {
 		ret = -EBUSY;
 		if (nn->nfsd_serv && nn->nfsd_serv->sv_nrthreads)
 			goto out_unlock;

 		ret = -EINVAL;
 		attr = info->attrs[NFSD_A_SERVER_GRACETIME];
 		if (attr) {
 			u32 gracetime = nla_get_u32(attr);

 			if (gracetime < 10 || gracetime > 3600)
 				goto out_unlock;

 			nn->nfsd4_grace = gracetime;
 		}

 		attr = info->attrs[NFSD_A_SERVER_LEASETIME];
 		if (attr) {
 			u32 leasetime = nla_get_u32(attr);

 			if (leasetime < 10 || leasetime > 3600)
 				goto out_unlock;

 			nn->nfsd4_lease = leasetime;
 		}

 		attr = info->attrs[NFSD_A_SERVER_SCOPE];
 		if (attr)
 			scope = nla_data(attr);
 	}

 	attr = info->attrs[NFSD_A_SERVER_MIN_THREADS];
 	if (attr)
 		nn->min_threads = nla_get_u32(attr);

-	ret = nfsd_svc(nrpools, nthreads, net, get_current_cred(), scope);
+	ret = nfsd_svc(nrpools, nthreads, net, current_cred(), scope);
 	if (ret > 0)
 		ret = 0;
 out_unlock:
 	mutex_unlock(&nfsd_mutex);
 	kfree(nthreads);
 	return ret;
 }



